import {DatabaseSync} from 'node:sqlite';import {mkdirSync} from 'node:fs';import path from 'node:path';import {canonicalSha256} from '../core/canonical-json.mjs';
const SHA=/^[a-f0-9]{64}$/;const ID=/^[A-Za-z0-9][A-Za-z0-9_-]{2,127}$/;
export class SqliteInstinctStore{
 constructor(file){this.file=path.resolve(file);mkdirSync(path.dirname(this.file),{recursive:true});this.db=new DatabaseSync(this.file);this.db.exec(`PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; CREATE TABLE IF NOT EXISTS forge_instincts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,project_id TEXT,harness TEXT,trust_domain TEXT NOT NULL,valid_until TEXT NOT NULL,payload TEXT NOT NULL) STRICT; CREATE INDEX IF NOT EXISTS forge_instinct_scope_idx ON forge_instincts(tenant_id,project_id,harness,valid_until);`);}
 close(){this.db.close();}
 async observe(input,{principal}={}){if(!principal?.roles?.includes('learning-observer'))throw new Error('Learning observer role required');if(input.maturity&&input.maturity!=='observed')throw new Error('Instinct maturity is assigned by the store and must remain observed');if(!ID.test(String(input.id??'')))throw new TypeError('Invalid instinct id');if(!input.scope?.tenantId)throw new TypeError('Instinct tenant scope is required');if(!input.pattern?.trim()||!input.mechanism?.trim())throw new TypeError('Instinct pattern and mechanism are required');if(!Array.isArray(input.sourceReceipts)||!input.sourceReceipts.length||input.sourceReceipts.some(x=>!SHA.test(String(x))))throw new TypeError('Trusted source receipt hashes are required');if(!Number.isFinite(input.confidence)||input.confidence<0||input.confidence>1)throw new TypeError('Instinct confidence must be between zero and one');const validUntil=new Date(input.validUntil);if(Number.isNaN(validUntil.valueOf()))throw new TypeError('Valid instinct expiry is required');const payload={schemaVersion:1,id:input.id,maturity:'observed',scope:{tenantId:String(input.scope.tenantId),projectId:input.scope.projectId?String(input.scope.projectId):null,harness:input.scope.harness?String(input.scope.harness):null},pattern:input.pattern.trim(),mechanism:input.mechanism.trim(),outcome:input.outcome??'unknown',confidence:input.confidence,validUntil:validUntil.toISOString(),sourceReceipts:[...input.sourceReceipts].sort(),trustDomain:principal.trustDomain??'unknown',observedBy:{id:principal.id,type:principal.type},observedAt:new Date().toISOString()};const stored={...payload,instinctSha256:canonicalSha256(payload)};this.db.prepare('INSERT INTO forge_instincts(id,tenant_id,project_id,harness,trust_domain,valid_until,payload) VALUES(?,?,?,?,?,?,?)').run(stored.id,stored.scope.tenantId,stored.scope.projectId,stored.scope.harness,stored.trustDomain,stored.validUntil,JSON.stringify(stored));return Object.freeze(stored);}
 async list({tenantId,projectId=null,harness=null,includeExpired=false}={}){if(!tenantId)throw new TypeError('Tenant scope is required');let sql='SELECT payload FROM forge_instincts WHERE tenant_id=?';const args=[tenantId];if(projectId){sql+=' AND project_id=?';args.push(projectId);}if(harness){sql+=' AND harness=?';args.push(harness);}if(!includeExpired){sql+=' AND valid_until>?';args.push(new Date().toISOString());}sql+=' ORDER BY id';return this.db.prepare(sql).all(...args).map(row=>JSON.parse(row.payload));}
}
